/**
 * 批量查询多个地址的 Turbine 代币余额
 * @param {string[]} addresses - 要查询的地址数组
 * @param {number} decimals - 代币精度（默认18）
 * @param {ethers.Provider} provider - ethers provider 实例（可选）
 * @returns {Promise<Array<{address: string, balance: bigint, balanceFormatted: string}>>} - 查询结果数组
 */
async function batchQueryTurbineBalances(addresses, decimals = 9, provider = null) {
    try {
        // 如果没有提供 provider，创建一个新的
        if (!provider) {
            provider = new ethers.JsonRpcProvider("https://polygon-bor-rpc.publicnode.com");
        }

        // 创建合约实例
        const turbineContract = new ethers.Contract(
            turbine_address,
            TURBINE_ABI,
            provider
        );

        console.log(`\n🔍 开始批量查询 ${addresses.length} 个地址的 Turbine 余额...`);

        // 批量查询余额
        const balancePromises = addresses.map(async (address) => {
            try {
                // 验证地址格式
                if (!ethers.isAddress(address)) {
                    console.warn(`⚠️ 跳过无效地址: ${address}`);
                    return {
                        address,
                        balance: 0n,
                        balanceFormatted: '0',
                        error: `无效的地址格式`
                    };
                }

                const balance = await turbineContract.getTurbineBal(address);
                const balanceFormatted = ethers.formatUnits(balance, decimals);

                return {
                    address,
                    balance,
                    balanceFormatted,
                    error: null
                };
            } catch (error) {
                console.error(`查询地址 ${address} 失败:`, error.message);
                return {
                    address,
                    balance: 0n,
                    balanceFormatted: '0',
                    error: error.message
                };
            }
        });

        // 等待所有查询完成
        const results = await Promise.all(balancePromises);

        // 统计结果
