/**
 * 查询指定地址的mint中质押数量
 * 
 * 使用方式：
 * node query_airdrop_energy_staking.js <用户地址> [RPC_URL]
 */





import { ethers } from 'ethers';

// 空投A和能量值质押合约地址列表
const AIRDROP_A_ENERGY_STAKE_CONTRACTS = [
    '0x14fcA7bfa779A4172c9b2DE61fd352C005442520',
    '0x23E2B07d85a8dbc307742C72aadbbdde4E5e2EFB',
    '0xDa13C7553A654601667adf9a1A16248bAB584F13',
    '0x65Ed60E414CEcE532d8afF90c89dA369E44CF883',
    '0x25a4b842cB200E9148FF5a11BAbF80488c8d8b07'
];

// 质押合约 ABI
const STAKE_ABI = [
    'function getUserStakesCount(address user) view returns (uint256)',
    'function stakes(address user, uint256 index) view returns (uint256 principal, uint256 gons, uint256 startBlock, uint256 expiry, uint256 warmup, uint256 lastBlock, uint256 vesting, bool exists)'
];

// 默认 RPC URL
const DEFAULT_RPC_URL = process.env.POLYGON_RPC_URL || 'https://dimensional-warmhearted-borough.matic.quiknode.pro/8d6b4c4e9e51944c650c74a447f3ae960c9f8cfe';

/**
 * 查询指定地址在指定合约中的质押数据
 */
async function queryUserStakes(userAddress, contractAddress, provider) {
    try {
        const contract = new ethers.Contract(contractAddress, STAKE_ABI, provider);

        // 1. 查询质押数量
        const count = await contract.getUserStakesCount(userAddress);
        const stakeCount = Number(count.toString());

        if (stakeCount === 0) {
            return [];
        }

        // 2. 查询每条质押数据
        const stakes = [];
        for (let i = 0; i < stakeCount; i++) {
            const stake = await contract.stakes(userAddress, i);
            stakes.push({
                index: i,
                principal: BigInt(stake.principal.toString()),
                gons: BigInt(stake.gons.toString()),
                startBlock: stake.startBlock.toString(),
                expiry: stake.expiry.toString(),
                warmup: stake.warmup.toString(),
                lastBlock: stake.lastBlock.toString(),
                vesting: stake.vesting.toString(),
                exists: stake.exists
            });
        }

        return stakes;
    } catch (error) {
        console.error(`查询失败 ${contractAddress}:`, error.message);
        return [];
    }
}

/**
 * 查询指定地址在所有空投A和能量值质押合约中的总质押
 */
async function queryAirdropAEnergyStaking(userAddress, rpcUrl = DEFAULT_RPC_URL) {
    if (!ethers.isAddress(userAddress)) {
        throw new Error(`无效的地址: ${userAddress}`);
    }

    console.log(`\n🔍 查询地址: ${userAddress}`);
    console.log(`📋 空投A和能量值质押合约数量: ${AIRDROP_A_ENERGY_STAKE_CONTRACTS.length}`);
    console.log(`🌐 RPC URL: ${rpcUrl}\n`);

    const provider = new ethers.JsonRpcProvider(rpcUrl);
    const allStakes = [];
    let totalPrincipal = 0n;

    // 遍历所有空投A和能量值质押合约
    for (const contractAddress of AIRDROP_A_ENERGY_STAKE_CONTRACTS) {
        console.log(`查询合约: ${contractAddress}`);
        const stakes = await queryUserStakes(userAddress, contractAddress, provider);

        if (stakes.length > 0) {
            console.log(`  ✅ 找到 ${stakes.length} 笔质押`);
            for (const stake of stakes) {
                allStakes.push({
                    contractAddress,
                    ...stake,
                    principalFormatted: ethers.formatUnits(stake.principal, 9)
                });
                totalPrincipal += stake.principal;
            }
        } else {
            console.log(`  ℹ️ 无质押记录`);
        }
    }

    return {
        userAddress,
        totalStakes: allStakes.length,
        totalPrincipal,
        totalPrincipalFormatted: ethers.formatUnits(totalPrincipal, 9),
        stakes: allStakes
    };
}

/**
 * 主函数
 */
async function main() {
    try {
        // 从命令行参数获取地址和 RPC URL
        const userAddress = "0x80cB03984E41CBdaE772D7090f66fa699A3CDF3F";
        const rpcUrl = process.argv[3] || DEFAULT_RPC_URL;

        if (!userAddress) {
            console.error('❌ 请提供用户地址');
            console.error('使用方式: node query_airdrop_energy_staking.js <用户地址> [RPC_URL]');
            process.exit(1);
        }

        // 查询数据
        const result = await queryAirdropAEnergyStaking(userAddress, rpcUrl);

        // 输出结果
        console.log('\n' + '='.repeat(80));
        console.log('📊 查询结果');
        console.log('='.repeat(80));
        console.log(`用户地址: ${result.userAddress}`);
        console.log(`总质押记录数: ${result.totalStakes}`);
        console.log(`总质押金额: ${result.totalPrincipalFormatted} LGNS`);

        if (result.stakes.length > 0) {
            console.log('\n详细质押记录:');
            for (const stake of result.stakes) {
                console.log(`  合约: ${stake.contractAddress}`);
                console.log(`    索引: ${stake.index}, 金额: ${stake.principalFormatted} LGNS`);
            }
        }

        console.log('\n✅ 查询完成！');

    } catch (error) {
        console.error('\n❌ 查询失败:', error.message);
        process.exit(1);
    }
}

// 如果直接运行此文件
if (process.argv[1] && process.argv[1].endsWith('query_airdrop_energy_staking.js')) {
    main().catch(console.error);
}

export { queryAirdropAEnergyStaking, queryUserStakes };

债券质押逻辑如下
/**
 * 查询债券质押总额模块
 * 
 * 功能：
 * 1. 查询单个地址的所有债券信息
 * 2. 计算债券质押总额
 * 3. 支持批量查询多个地址的债券数据
 */

import { ethers } from 'ethers';
import * as dotenv from 'dotenv';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import { existsSync } from 'fs';
import { long_bonds_abi } from '../7702/long_bonds_abi.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const parentDir = join(__dirname, '..');

const envPath = existsSync(join(__dirname, '.env'))
    ? join(__dirname, '.env')
    : existsSync(join(parentDir, '.env'))
        ? join(parentDir, '.env')
        : undefined;

if (envPath) {
    dotenv.config({ path: envPath });
    console.log('📁 已加载 .env 文件:', envPath);
} else {
    console.log('⚠️ 未找到 .env 文件，将使用默认值或系统环境变量');
    dotenv.config();
}

// 债券合约地址列表（参考 batch_claim_all_bonds.js 和 zhaiquan_bonds_mod.js）
const BOND_CONTRACT_ADDRESSES = [
    "0x6c0ac888b075c6b5141cbc1da6170b6686afd07d",
];
// 保留单个地址变量以保持向后兼容
const BOND_CONTRACT_ADDRESS = BOND_CONTRACT_ADDRESSES[0];

// 阈值：0.2 LGNS（精度9，所以是 0.2 * 10^9）
// 用于筛选超过阈值的债券，如果不需要筛选可以设置为 0
const THRESHOLD_LGNS = 0.2;
const THRESHOLD_WEI = BigInt(Math.floor(THRESHOLD_LGNS * 1e9));

/**
 * 查询用户的所有债券信息（参考 batch_claim_all_bonds.js 的实现）
 * 查询所有债券合约地址的债券数据
 * 
 * @param {string} userAddress - 用户地址
 * @param {ethers.Provider} provider - 以太坊提供者
 * @param {bigint} threshold - 阈值（wei），只返回超过阈值的债券，如果为 0n 则返回所有债券
 * @returns {Promise<Array>} 债券信息数组
 */
export async function queryUserBonds(userAddress, provider, threshold = THRESHOLD_WEI) {
    const allBonds = [];

    // 遍历所有债券合约地址
    for (const contractAddress of BOND_CONTRACT_ADDRESSES) {
        try {
            const contract = new ethers.Contract(contractAddress, long_bonds_abi, provider);
            const bondCount = await contract.getBondInfoDataLength(userAddress);
            const count = Number(bondCount.toString());

            if (process.env.DEBUG_BONDS === 'true') {
                console.log(`   🔍 ${userAddress}: 合约 ${contractAddress} 债券总数 = ${count}`);
            }

            if (count === 0) {
                continue;
            }

            const bonds = [];
            const promises = [];

            for (let i = 0; i < count; i++) {
                promises.push(
                    contract.bondInfoData(userAddress, i)
                        .then(bondInfo => {
                            // 验证债券数据有效性
                            // 注意：bondInfo.id 可以是 0，只要 owner 不是零地址就是有效的
                            if (bondInfo && bondInfo.owner && bondInfo.owner !== ethers.ZeroAddress) {
                                const payout = BigInt(bondInfo.payout.toString());
                                const pricePaid = BigInt(bondInfo.pricePaid.toString());

                                // 债券的 principal 是 pricePaid（用户投入的金额），但统计时使用 payout（总支付金额）
                                // 这里使用 payout 作为统计依据，因为用户关心的是总支付金额
                                const principal = payout;

                                // 如果设置了阈值，只返回超过阈值的债券
                                if (threshold === 0n || principal >= threshold) {
                                    bonds.push({
                                        index: i,
                                        bondId: bondInfo.id.toString(),
                                        owner: bondInfo.owner,
                                        contractAddress: contractAddress, // 记录债券所属的合约地址
                                        payout: payout,
                                        payoutFormatted: ethers.formatUnits(payout, 9),
                                        pricePaid: pricePaid,
                                        pricePaidFormatted: ethers.formatUnits(pricePaid, 9),
                                        vesting: bondInfo.vesting.toString(),
                                        lastBlock: bondInfo.lastBlock.toString(),
                                        // 债券的 principal 使用 payout（总支付金额）作为统计依据
                                        principal: principal,
                                        principalFormatted: ethers.formatUnits(principal, 9)
                                    });
                                }
                            }
                            return null;
                        })
                        .catch(err => {
                            // 忽略单个查询错误
                            if (process.env.DEBUG_BONDS === 'true') {
                                console.log(`      ⚠️ 查询债券索引 ${i} 失败: ${err.message}`);
                            }
                            return null;
                        })
                );
            }

            await Promise.all(promises);

            if (bonds.length > 0) {
                if (process.env.DEBUG_BONDS === 'true') {
                    console.log(`   ✅ ${userAddress}: 合约 ${contractAddress} 查询到 ${bonds.length} 笔${threshold > 0n ? '超过阈值' : ''}的债券`);
                    bonds.forEach((bond, idx) => {
                        console.log(`      [${idx}] 债券ID: ${bond.bondId}, payout: ${bond.payoutFormatted} LGNS`);
                    });
                }
                allBonds.push(...bonds);
            }
        } catch (error) {
            console.error(`❌ 查询债券失败 ${userAddress} (合约 ${contractAddress}):`, error.message);
            if (process.env.DEBUG_BONDS === 'true') {
                console.error(`   错误详情:`, error);
            }
            // 继续查询下一个合约
            continue;
        }
    }

    if (process.env.DEBUG_BONDS === 'true' && allBonds.length > 0) {
        console.log(`   📊 ${userAddress}: 总共查询到 ${allBonds.length} 笔债券（跨所有合约）`);
    }

    // 按合约地址和索引排序
    return allBonds.sort((a, b) => {
        const addrCompare = a.contractAddress.localeCompare(b.contractAddress);
        if (addrCompare !== 0) return addrCompare;
        return a.index - b.index;
    });
}

/**
 * 计算用户债券质押总额
 * 
 * @param {string} userAddress - 用户地址
 * @param {ethers.Provider} provider - 以太坊提供者
 * @param {bigint} threshold - 阈值（wei），只统计超过阈值的债券，如果为 0n 则统计所有债券
 * @returns {Promise<bigint>} 债券质押总额（wei，精度9）
 */
export async function queryUserBondStakingTotal(userAddress, provider, threshold = 0n) {
    try {
        const bonds = await queryUserBonds(userAddress, provider, threshold);

        // 计算所有债券的质押总额
        const total = bonds.reduce((sum, bond) => sum + bond.principal, 0n);

        return total;
    } catch (error) {
        console.error(`❌ 计算债券质押总额失败 ${userAddress}:`, error.message);
        return 0n;
    }
}

/**
 * 批量查询多个地址的债券质押总额
 * 
 * @param {string[]} userAddresses - 用户地址数组
 * @param {ethers.Provider} provider - 以太坊提供者
 * @param {bigint} threshold - 阈值（wei），只统计超过阈值的债券，如果为 0n 则统计所有债券
 * @param {number} delay - 每个请求之间的延迟（毫秒），默认100ms
 * @returns {Promise<Map<string, {total: bigint, count: number}>>} 地址到债券质押总额和数量的映射
 */
export async function batchQueryBondStakingTotal(userAddresses, provider, threshold = 0n, delay = 100) {
    const results = new Map();

    console.log(`\n🔍 开始批量查询 ${userAddresses.length} 个地址的债券质押总额...`);
    console.log(`   债券合约地址列表: ${BOND_CONTRACT_ADDRESSES.join(', ')}`);
    if (threshold > 0n) {
        console.log(`   阈值: ${ethers.formatUnits(threshold, 9)} LGNS`);
    }

    let totalBondsFound = 0;
    let addressesWithBonds = 0;

    for (let i = 0; i < userAddresses.length; i++) {
        const userAddr = userAddresses[i];

        if (i % 10 === 0) {
            console.log(`   进度: ${i}/${userAddresses.length}`);
        }

        try {
            const bonds = await queryUserBonds(userAddr, provider, threshold);

            if (bonds.length > 0) {
                totalBondsFound += bonds.length;
                addressesWithBonds++;

                const total = bonds.reduce((sum, bond) => sum + bond.principal, 0n);
                results.set(userAddr, {
                    total: total,
                    count: bonds.length,
                    bonds: bonds
                });

                console.log(`   📊 ${userAddr}: 找到 ${bonds.length} 笔债券，总额 ${ethers.formatUnits(total, 9)} LGNS`);
            } else {
                results.set(userAddr, {
                    total: 0n,
                    count: 0,
                    bonds: []
                });
            }
        } catch (error) {
            console.error(`   ❌ ${userAddr}: 查询债券失败 - ${error.message}`);
            results.set(userAddr, {
                total: 0n,
                count: 0,
                bonds: []
            });
        }

        // 添加延迟，避免请求过快
        if (i < userAddresses.length - 1) {
            await new Promise(resolve => setTimeout(resolve, delay));
        }
    }

    // 输出统计信息
    console.log(`\n📊 债券查询统计:`);
    console.log(`   总查询地址数: ${userAddresses.length}`);
    console.log(`   有债券的地址数: ${addressesWithBonds}`);
    console.log(`   总债券记录数: ${totalBondsFound}`);

    const totalAmount = Array.from(results.values()).reduce((sum, r) => sum + r.total, 0n);
    console.log(`   总债券金额: ${ethers.formatUnits(totalAmount, 9)} LGNS`);

    console.log(`\n✅ 批量查询完成`);

    return results;
}

/**
