      remark: "Main Account",
      derivedAddress: "0x309ca717d6989676194b88fd06029a88ceefee60"
    }
];

export default function App() {
    const [addresses, setAddresses] = useState<AddressEntry[]>([]);
    const [stakingData, setStakingData] = useState<Record<string, StakingData>>({});
    const [rpcUrl, setRpcUrl] = useState(DEFAULT_RPC);
    const [searchTerm, setSearchTerm] = useState('');
    const [loading, setLoading] = useState(false);
    const [editingRemark, setEditingRemark] = useState<{ address: string, value: string } | null>(null);

    useEffect(() => {
        const saved = localStorage.getItem('polygon_addresses');
        if (saved) {
            setAddresses(JSON.parse(saved));
        } else {
            setAddresses(INITIAL_ADDRESSES);
        }

        const savedStats = localStorage.getItem('polygon_staking_stats');
        if (savedStats) {
            setStakingData(JSON.parse(savedStats));
        }
    }, []);

    const saveAddresses = (newAddresses: AddressEntry[]) => {
        setAddresses(newAddresses);
        localStorage.setItem('polygon_addresses', JSON.stringify(newAddresses));
    };

    const handleRefresh = async () => {
        if (addresses.length === 0) return;
        setLoading(true);
        try {
            const service = new BlockchainService(rpcUrl);
            const results = await service.batchQuery(addresses);
            const newStakingData = Object.fromEntries(results);
            setStakingData(newStakingData);
            localStorage.setItem('polygon_staking_stats', JSON.stringify(newStakingData));
        } catch (error) {
            console.error("Refresh failed", error);
            alert("Query failed. Please check your RPC URL or network connection.");
        } finally {
            setLoading(false);
        }
    };

    const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (event) => {
            try {
                const json = JSON.parse(event.target?.result as string);
                let importedItems: AddressEntry[] = [];
                if (Array.isArray(json)) {
                    importedItems = json;
                } else if (json.items && Array.isArray(json.items)) {
                    importedItems = json.items;
                }

                if (importedItems.length > 0) {
                    saveAddresses(importedItems);
                    alert(`Successfully imported ${importedItems.length} addresses!`);
                }
            } catch (err) {
                alert("Invalid file format. Please import a valid JSON file.");
            }
        };
        reader.readAsText(file);
    };

    const handleExport = () => {
        const exportData = {
            generatedAt: new Date().toISOString(),
            total: addresses.length,
            items: addresses
        };
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData, null, 2));
        const downloadAnchorNode = document.createElement('a');
