                        className={`flex items-center justify-center gap-2 px-6 py-2 rounded-lg font-semibold transition-all shadow-lg ${
                            loading ? 'bg-slate-700 cursor-not-allowed text-slate-400' : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-indigo-500/20'
                        }`}
                    >
                        <RefreshCcw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
