                <StatCard icon={<ArrowUpRight className="text-purple-400" />} label="Bond Staking" value={stats.totalBond} color="purple" />
                <StatCard icon={<Wallet className="text-emerald-400" />} label="Turbine Bal" value={stats.totalTurbine} color="emerald" />
