                    Powered by <span className="font-bold text-slate-400">Multicall3</span> on Polygon Network
                </p>
                {Object.keys(stakingData).length > 0 && (
                    <p className="mt-2 bg-slate-800/50 inline-block px-3 py-1 rounded-full border border-slate-700">
                        Latest sync: {new Date(Object.values(stakingData)[0].lastUpdated || 0).toLocaleString()}
                    </p>
                )}
            </footer>
        </div>
    );
}

function StatCard({ icon, label, value, color }: { icon: React.ReactNode, label: string, value: number, color: string }) {
    return (
        <div className={`bg-slate-800/40 border border-slate-700 p-5 rounded-2xl hover:border-${color}-500/50 transition-all hover:shadow-lg hover:shadow-${color}-500/5`}>
            <div className="flex items-center gap-3 mb-3">
                <div className={`p-2 bg-slate-900 rounded-lg`}>{icon}</div>
                <span className="text-xs font-bold uppercase tracking-widest text-slate-500">{label}</span>
            </div>
            <div className="text-2xl font-bold text-white truncate">
                {value.toLocaleString(undefined, { maximumFractionDigits: 2 })}
                <span className="text-[10px] ml-1 text-slate-600 font-normal">LGNS</span>
            </div>
        </div>
    );
}

function formatNum(val: string) {
    const n = parseFloat(val);
    if (isNaN(n)) return '0.00';
    return n.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 4 });
}

