import { ethers } from 'ethers';
import { 
    MULTICALL3_ADDRESS, 
    MULTICALL3_ABI, 
    ERC20_ABI, 
    STAKE_ABI, 
    BOND_ABI, 
    TURBINE_ABI, 
    SPIDER_WEB_ABI,
    TOTAL_STAKE_MULTICALL_ABI,
    MINT_STAKE_CONTRACTS,
    BOND_CONTRACTS,
    TURBINE_CONTRACT,
    SPIDER_WEB_CONTRACT,
    TOTAL_STAKING_QUERY_CONTRACT,
    TOKEN_LGNS,
    TOKEN_SLGNS
} from '../constants';
import { AddressEntry, StakingData } from '../types';

export class BlockchainService {
    private provider: ethers.JsonRpcProvider;
    private multicallContract: ethers.Contract;

    constructor(rpcUrl: string) {
        this.provider = new ethers.JsonRpcProvider(rpcUrl);
        this.multicallContract = new ethers.Contract(MULTICALL3_ADDRESS, MULTICALL3_ABI, this.provider);
    }

    private encodeCall(contractInterface: ethers.Interface, fnName: string, args: any[]): string {
        return contractInterface.encodeFunctionData(fnName, args);
    }

    private decodeResult(contractInterface: ethers.Interface, fnName: string, data: string): any {
        try {
            return contractInterface.decodeFunctionResult(fnName, data);
        } catch (e) {
            return null;
        }
    }

    private async queryTotalStaking(address: string): Promise<bigint> {
        try {
            const userAddress_outwith0x = address.slice(2).toLowerCase();
            const callData = `${userAddress_outwith0x}00000000000000000000000000000000000000000000000000000000`;

            const result = await this.provider.call({
                to: TOTAL_STAKING_QUERY_CONTRACT,
                data: callData.startsWith('0x') ? callData : '0x' + callData
            });

            if (!result || result === '0x') return 0n;

            const multicallInterface = new ethers.Interface(TOTAL_STAKE_MULTICALL_ABI);
            const decoded = multicallInterface.decodeFunctionResult('multiCall', result);
            const results = decoded[1]; 

            if (results && results.length > 1 && results[1] !== '0x' && results[1].length === 66) {
                return BigInt(results[1]);
            }
            return 0n;
        } catch (e) {
            return 0n;
        }
    }

    async batchQuery(addresses: AddressEntry[]): Promise<Map<string, StakingData>> {
        const resultsMap = new Map<string, StakingData>();

        const erc20Int = new ethers.Interface(ERC20_ABI);
        const stakeInt = new ethers.Interface(STAKE_ABI);
        const bondInt = new ethers.Interface(BOND_ABI);
        const turbineInt = new ethers.Interface(TURBINE_ABI);
        const spiderInt = new ethers.Interface(SPIDER_WEB_ABI);

        // Small chunks to avoid "out of result range" or Gas limits
        const chunkSize = 10;
        for (let i = 0; i < addresses.length; i += chunkSize) {
            const chunk = addresses.slice(i, i + chunkSize);
            const firstPassCalls: any[] = [];

            chunk.forEach(addr => {
                // Common balance/reward calls
                firstPassCalls.push({ target: TURBINE_CONTRACT, allowFailure: true, callData: this.encodeCall(turbineInt, 'getTurbineBal', [addr.aAddress]) });
                firstPassCalls.push({ target: SPIDER_WEB_CONTRACT, allowFailure: true, callData: this.encodeCall(spiderInt, 'claimable', [addr.aAddress]) });
                firstPassCalls.push({ target: TOKEN_LGNS.address, allowFailure: true, callData: this.encodeCall(erc20Int, 'balanceOf', [addr.derivedAddress]) });
                firstPassCalls.push({ target: TOKEN_SLGNS.address, allowFailure: true, callData: this.encodeCall(erc20Int, 'balanceOf', [addr.derivedAddress]) });

                // Get counts for staking/bonds
                MINT_STAKE_CONTRACTS.forEach(contract => {
                    firstPassCalls.push({ target: contract, allowFailure: true, callData: this.encodeCall(stakeInt, 'getUserStakesCount', [addr.aAddress]) });
                });
                BOND_CONTRACTS.forEach(contract => {
                    firstPassCalls.push({ target: contract, allowFailure: true, callData: this.encodeCall(bondInt, 'getBondInfoDataLength', [addr.aAddress]) });
                });
            });

            const firstPassResponse = await this.multicallContract.aggregate3(firstPassCalls);
            let callIdx = 0;

            for (const addr of chunk) {
                const turbineRaw = firstPassResponse[callIdx++];
                const spiderRaw = firstPassResponse[callIdx++];
                const lgnsRaw = firstPassResponse[callIdx++];
                const slgnsRaw = firstPassResponse[callIdx++];

                const turbineBal = (turbineRaw && turbineRaw.success && turbineRaw.returnData !== '0x') ? this.decodeResult(turbineInt, 'getTurbineBal', turbineRaw.returnData)[0] : 0n;
                const spiderReward = (spiderRaw && spiderRaw.success && spiderRaw.returnData !== '0x') ? this.decodeResult(spiderInt, 'claimable', spiderRaw.returnData)[0] : 0n;
                const lgnsBal = (lgnsRaw && lgnsRaw.success && lgnsRaw.returnData !== '0x') ? this.decodeResult(erc20Int, 'balanceOf', lgnsRaw.returnData)[0] : 0n;
                const slgnsBal = (slgnsRaw && slgnsRaw.success && slgnsRaw.returnData !== '0x') ? this.decodeResult(erc20Int, 'balanceOf', slgnsRaw.returnData)[0] : 0n;

                const mintCounts: number[] = [];
                MINT_STAKE_CONTRACTS.forEach(() => {
                    const res = firstPassResponse[callIdx++];
                    mintCounts.push((res && res.success && res.returnData !== '0x') ? Number(this.decodeResult(stakeInt, 'getUserStakesCount', res.returnData)[0]) : 0);
                });

                const bondCounts: number[] = [];
                BOND_CONTRACTS.forEach(() => {
                    const res = firstPassResponse[callIdx++];
                    bondCounts.push((res && res.success && res.returnData !== '0x') ? Number(this.decodeResult(bondInt, 'getBondInfoDataLength', res.returnData)[0]) : 0);
                });

                // Detail calls for Mint/Bond totals
                const detailCalls: any[] = [];
                MINT_STAKE_CONTRACTS.forEach((contract, cIdx) => {
                    for (let sIdx = 0; sIdx < mintCounts[cIdx]; sIdx++) {
                        detailCalls.push({ target: contract, allowFailure: true, callData: this.encodeCall(stakeInt, 'stakes', [addr.aAddress, sIdx]) });
                    }
                });
                BOND_CONTRACTS.forEach((contract, cIdx) => {
                    for (let bIdx = 0; bIdx < bondCounts[cIdx]; bIdx++) {
                        detailCalls.push({ target: contract, allowFailure: true, callData: this.encodeCall(bondInt, 'bondInfoData', [addr.aAddress, bIdx]) });
                    }
                });

                let totalMintPrincipal = 0n;
                let totalBondPayout = 0n;

                if (detailCalls.length > 0) {
                    try {
                        const detailResponse = await this.multicallContract.aggregate3(detailCalls);
                        let dIdx = 0;
                        MINT_STAKE_CONTRACTS.forEach((_, cIdx) => {
                            for (let sIdx = 0; sIdx < mintCounts[cIdx]; sIdx++) {
                                const res = detailResponse[dIdx++];
                                if (res && res.success && res.returnData !== '0x') {
                                    const decoded = this.decodeResult(stakeInt, 'stakes', res.returnData);
                                    if (decoded) totalMintPrincipal += BigInt(decoded.principal);
                                }
                            }
                        });
                        BOND_CONTRACTS.forEach((_, cIdx) => {
                            for (let bIdx = 0; bIdx < bondCounts[cIdx]; bIdx++) {
                                const res = detailResponse[dIdx++];
                                if (res && res.success && res.returnData !== '0x') {
                                    const decoded = this.decodeResult(bondInt, 'bondInfoData', res.returnData);
                                    if (decoded) totalBondPayout += BigInt(decoded.payout);
                                }
                            }
                        });
                    } catch (e) {
                        console.error("Detail query failed for", addr.aAddress, e);
                    }
                }

                // Call the special total staking function
                const totalStakingValue = await this.queryTotalStaking(addr.aAddress);

                resultsMap.set(addr.aAddress, {
                    totalStaking: ethers.formatUnits(totalStakingValue, 9),
                    mintStaking: ethers.formatUnits(totalMintPrincipal, 9),
                    bondStaking: ethers.formatUnits(totalBondPayout, 9),
                    spiderWebReward: ethers.formatUnits(spiderReward, 9),
                    turbineBalance: ethers.formatUnits(turbineBal, 9),
                    derivedLgns: ethers.formatUnits(lgnsBal, TOKEN_LGNS.decimals),
                    derivedSlgns: ethers.formatUnits(slgnsBal, TOKEN_SLGNS.decimals),
                    lastUpdated: Date.now()
                });
            }
        }
        return resultsMap;
    }
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
    Search, 
    RefreshCcw, 
    Download, 
    Upload, 
    Edit2, 
    Save, 
    X, 
    Database, 
    Activity, 
    Wallet,
    Info,
    ListFilter,
    ArrowUpRight,
    TrendingUp,
    Coins,
    Layers
} from 'lucide-react';
import { AddressEntry, StakingData } from './types';
import { DEFAULT_RPC } from './constants';
import { BlockchainService } from './services/blockchainService';

const INITIAL_ADDRESSES: AddressEntry[] = [
    {
      aAddress: "0x80cB03984E41CBdaE772D7090f66fa699A3CDF3F",
      log: "5月20号",
      remark: "Default Demo",
      derivedAddress: "0x309ca717d6989676194b88fd06029a88ceefee60",
      split: "5-5开"
    }
];

export default function App() {
    const [addresses, setAddresses] = useState<AddressEntry[]>([]);
    const [stakingData, setStakingData] = useState<Record<string, StakingData>>({});
    const [rpcUrl, setRpcUrl] = useState(DEFAULT_RPC);
    const [searchTerm, setSearchTerm] = useState('');
    const [loading, setLoading] = useState(false);
    const [editingRemark, setEditingRemark] = useState<{ address: string, value: string } | null>(null);

    useEffect(() => {
        const saved = localStorage.getItem('polygon_addresses');
        if (saved) {
            setAddresses(JSON.parse(saved));
        } else {
            setAddresses(INITIAL_ADDRESSES);
        }

        const savedStats = localStorage.getItem('polygon_staking_stats');
        if (savedStats) {
            setStakingData(JSON.parse(savedStats));
        }
    }, []);

    const saveAddresses = (newAddresses: AddressEntry[]) => {
        // Deduplicate by aAddress
        const uniqueMap = new Map();
        newAddresses.forEach(item => {
            if (item.aAddress) {
                uniqueMap.set(item.aAddress.toLowerCase(), item);
            }
        });
        const finalAddresses = Array.from(uniqueMap.values());
        setAddresses(finalAddresses);
        localStorage.setItem('polygon_addresses', JSON.stringify(finalAddresses));
    };

    const handleRefresh = async () => {
        if (addresses.length === 0) return;
        setLoading(true);
        try {
            const service = new BlockchainService(rpcUrl);
            const results = await service.batchQuery(addresses);
            const newStakingData = Object.fromEntries(results);
            setStakingData(prev => ({ ...prev, ...newStakingData }));
            localStorage.setItem('polygon_staking_stats', JSON.stringify({ ...stakingData, ...newStakingData }));
        } catch (error) {
            console.error("Refresh error:", error);
            alert("Query failed. Check console for details. Common causes: RPC rate limiting or block explorer timeouts.");
        } finally {
            setLoading(false);
        }
    };

    const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (event) => {
            try {
                const json = JSON.parse(event.target?.result as string);
                let importedItems: AddressEntry[] = [];
                if (Array.isArray(json)) {
                    importedItems = json;
                } else if (json.items && Array.isArray(json.items)) {
                    importedItems = json.items;
                }

                if (importedItems.length > 0) {
                    saveAddresses(importedItems);
                    alert(`Successfully imported ${importedItems.length} addresses!`);
                }
            } catch (err) {
                alert("Invalid file format. Please import a valid JSON file.");
            }
        };
        reader.readAsText(file);
    };

    const handleExport = () => {
        const exportData = {
            generatedAt: new Date().toISOString(),
            total: addresses.length,
            items: addresses
        };
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData, null, 2));
        const downloadAnchorNode = document.createElement('a');
        downloadAnchorNode.setAttribute("href", dataStr);
        downloadAnchorNode.setAttribute("download", `polygon_export_${new Date().getTime()}.json`);
        document.body.appendChild(downloadAnchorNode);
        downloadAnchorNode.click();
        downloadAnchorNode.remove();
    };

    const handleUpdateRemark = (address: string, newRemark: string) => {
        const newAddresses = addresses.map(a => a.aAddress === address ? { ...a, remark: newRemark } : a);
        saveAddresses(newAddresses);
        setEditingRemark(null);
    };

    const filteredAddresses = useMemo(() => {
        return addresses.filter(a => 
            (a.remark || "").toLowerCase().includes(searchTerm.toLowerCase()) || 
            (a.aAddress || "").toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [addresses, searchTerm]);

    const stats = useMemo(() => {
        let totalVal = 0;
        let totalTurbine = 0;
        let totalSpider = 0;
        let totalMint = 0;
        let totalBond = 0;
        let totalDerivedLgns = 0;
        let totalDerivedSlgns = 0;

        // Sum only for the addresses currently in the database to avoid stale data inflating totals
        addresses.forEach(addr => {
            const data = stakingData[addr.aAddress];
            if (data) {
                totalVal += parseFloat(data.totalStaking) || 0;
                totalTurbine += parseFloat(data.turbineBalance) || 0;
                totalSpider += parseFloat(data.spiderWebReward) || 0;
                totalMint += parseFloat(data.mintStaking) || 0;
                totalBond += parseFloat(data.bondStaking) || 0;
                totalDerivedLgns += parseFloat(data.derivedLgns) || 0;
                totalDerivedSlgns += parseFloat(data.derivedSlgns) || 0;
            }
        });
        return { totalVal, totalTurbine, totalSpider, totalMint, totalBond, totalDerivedLgns, totalDerivedSlgns };
    }, [stakingData, addresses]);

    return (
        <div className="max-w-7xl mx-auto px-4 py-8">
            <header className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 mb-8">
                <div>
                    <h1 className="text-3xl font-bold text-white flex items-center gap-3">
                        <Database className="text-indigo-400 w-8 h-8" />
                        Polygon Data Hub
                    </h1>
                    <p className="text-slate-400 mt-2">Deduplicated multi-module tracking for Polygon Network projects</p>
                </div>

                <div className="flex flex-wrap items-center gap-3 w-full lg:w-auto">
                    <div className="relative flex-1 lg:flex-none">
                        <input 
                            type="text" 
                            value={rpcUrl}
                            onChange={(e) => setRpcUrl(e.target.value)}
                            placeholder="RPC URL"
                            className="bg-slate-800 border border-slate-700 text-slate-200 rounded-lg px-3 py-2 text-sm w-full lg:w-72 focus:ring-2 focus:ring-indigo-500 outline-none"
                        />
                    </div>
                    <button 
                        onClick={handleRefresh}
                        disabled={loading || addresses.length === 0}
                        className={`flex items-center justify-center gap-2 px-6 py-2 rounded-lg font-semibold transition-all shadow-lg ${
                            loading ? 'bg-slate-700 cursor-not-allowed text-slate-400' : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-indigo-500/20'
                        }`}
                    >
                        <RefreshCcw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
                        {loading ? 'Batch Querying...' : 'Sync Data'}
                    </button>
                </div>
            </header>

            {/* Summaries */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-4">
                <StatCard icon={<Activity className="text-indigo-400" />} label="Total Staking" value={stats.totalVal} color="indigo" />
                <StatCard icon={<TrendingUp className="text-blue-400" />} label="Mint Staking" value={stats.totalMint} color="blue" />
                <StatCard icon={<ArrowUpRight className="text-purple-400" />} label="Bond Staking" value={stats.totalBond} color="purple" />
                <StatCard icon={<Wallet className="text-emerald-400" />} label="Turbine Bal" value={stats.totalTurbine} color="emerald" />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-8">
                <StatCard icon={<Info className="text-amber-400" />} label="Spider Web" value={stats.totalSpider} color="amber" />
                <StatCard icon={<Coins className="text-pink-400" />} label="Total Derived LGNS" value={stats.totalDerivedLgns} color="pink" />
                <StatCard icon={<Layers className="text-cyan-400" />} label="Total Derived slgns" value={stats.totalDerivedSlgns} color="cyan" />
            </div>

            <div className="bg-slate-800 border border-slate-700 p-4 rounded-xl flex flex-col md:flex-row justify-between items-center gap-4 mb-6 shadow-xl">
                <div className="relative w-full md:w-96">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                    <input 
                        type="text" 
                        placeholder="Search by remark or address..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="bg-slate-900 border border-slate-700 text-slate-200 rounded-lg pl-10 pr-4 py-2 w-full focus:ring-1 focus:ring-indigo-500 outline-none"
                    />
                </div>
                <div className="flex items-center gap-3 w-full md:w-auto">
                    <label className="flex-1 md:flex-none flex items-center justify-center gap-2 px-5 py-2 bg-slate-700 hover:bg-slate-600 text-slate-100 rounded-lg cursor-pointer text-sm font-semibold transition-all">
                        <Upload className="w-4 h-4" />
                        Import
                        <input type="file" className="hidden" accept=".json" onChange={handleImport} />
                    </label>
                    <button 
                        onClick={handleExport}
                        className="flex-1 md:flex-none flex items-center justify-center gap-2 px-5 py-2 bg-slate-700 hover:bg-slate-600 text-slate-100 rounded-lg text-sm font-semibold transition-all"
                    >
                        <Download className="w-4 h-4" />
                        Export
                    </button>
                </div>
            </div>

            <div className="bg-slate-800 border border-slate-700 rounded-2xl overflow-hidden shadow-2xl">
                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="bg-slate-900/50 border-b border-slate-700 text-[10px] font-bold text-slate-400 uppercase tracking-wider">
                                <th className="px-4 py-3">Remark / Address</th>
                                <th className="px-4 py-3 text-right">Mint / Bond</th>
                                <th className="px-4 py-3 text-right">Total Staking</th>
                                <th className="px-4 py-3 text-right">Rewards (T/S)</th>
                                <th className="px-4 py-3">Derived (L/S)</th>
                                <th className="px-4 py-3">Log / Split</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-700/50">
                            {filteredAddresses.map((addr) => {
                                const data = stakingData[addr.aAddress] || {
                                    totalStaking: '0.0',
                                    mintStaking: '0.0',
                                    bondStaking: '0.0',
                                    spiderWebReward: '0.0',
                                    turbineBalance: '0.0',
                                    derivedLgns: '0.0',
                                    derivedSlgns: '0.0'
                                };

                                return (
                                    <tr key={addr.aAddress} className="group hover:bg-slate-700/30 transition-all">
                                        <td className="px-4 py-4 min-w-[200px]">
                                            <div className="flex flex-col gap-1">
                                                <div className="flex items-center gap-2">
                                                    {editingRemark?.address === addr.aAddress ? (
                                                        <div className="flex items-center gap-1">
                                                            <input 
                                                                autoFocus
                                                                className="bg-slate-900 border border-indigo-500 rounded px-2 py-0.5 text-xs text-slate-100 outline-none w-32"
                                                                value={editingRemark.value}
                                                                onChange={(e) => setEditingRemark({ ...editingRemark, value: e.target.value })}
                                                                onBlur={() => handleUpdateRemark(addr.aAddress, editingRemark.value)}
                                                                onKeyDown={(e) => {
