                    <button 
                        onClick={handleRefresh}
                        disabled={loading || addresses.length === 0}
                        className={`flex items-center justify-center gap-2 px-8 py-3 rounded-xl font-black text-sm transition-all shadow-2xl ${
                            loading ? 'bg-slate-700 cursor-not-allowed text-slate-400' : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-indigo-600/40 hover:-translate-y-0.5 active:translate-y-0'
