                                                <span className="text-[13px] font-black text-emerald-400 tracking-tight">TURB: {formatNum(data.turbineBalance)}</span>
                                                <span className="text-[13px] font-black text-amber-400 tracking-tight">SPID: {formatNum(data.spiderWebReward)}</span>
