                                            </div>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
                {filteredAddresses.length === 0 && (
                    <div className="p-32 text-center bg-slate-900/20">
                        <ListFilter className="w-24 h-24 text-slate-800 mx-auto mb-8 animate-pulse" />
                        <p className="text-slate-500 font-black text-2xl italic tracking-tight">No matching results in your polygon database.</p>
                        <button onClick={() => setSearchTerm('')} className="mt-6 px-8 py-3 bg-slate-800 text-indigo-400 hover:bg-slate-700 rounded-2xl font-black transition-all">Reset All Filters</button>
                    </div>
                )}
            </div>

            <footer className="mt-16 text-center">
                <div className="inline-flex flex-col items-center gap-3 px-10 py-8 bg-slate-800/30 rounded-[2.5rem] border border-slate-700/50 backdrop-blur-sm">
                    <div className="flex items-center gap-6">
                        <div className="flex flex-col items-center">
                            <span className="text-[10px] font-black text-slate-600 uppercase tracking-widest mb-1">Deduplicated Items</span>
                            <span className="text-2xl font-black text-indigo-400">{addresses.length}</span>
                        </div>
                        <div className="w-px h-10 bg-slate-700"></div>
                        <div className="flex flex-col items-center">
                            <span className="text-[10px] font-black text-slate-600 uppercase tracking-widest mb-1">Network Speed</span>
                            <span className="text-2xl font-black text-emerald-400">Optimized</span>
                        </div>
                    </div>
                    <p className="text-slate-700 text-[10px] font-black uppercase tracking-widest mt-2">© 2025 Polygon Visualizer • Powered by Multicall V3 & ethers.js</p>
                </div>
