        <div className={`bg-slate-800/40 border-2 border-slate-700/40 p-5 rounded-3xl hover:border-${color}-500/50 transition-all hover:shadow-[0_20px_40px_rgba(0,0,0,0.4)] group relative overflow-hidden`}>
            <div className={`absolute top-0 right-0 w-24 h-24 bg-${color}-500/5 rounded-full -mr-12 -mt-12 transition-transform group-hover:scale-150`}></div>
            <div className="flex items-center gap-3 mb-4 relative z-10">
