            </header>

            {/* Global Summaries */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-7 gap-4 mb-10">
                <StatCard icon={<Activity className="text-indigo-400" />} label="Total Staking" value={globalStats.val} color="indigo" />
                <StatCard icon={<TrendingUp className="text-blue-400" />} label="Mint Total" value={globalStats.mint} color="blue" />
                <StatCard icon={<ArrowUpRight className="text-purple-400" />} label="Bond Total" value={globalStats.bond} color="purple" />
                <StatCard icon={<Wallet className="text-emerald-400" />} label="Turbine Bal" value={globalStats.turb} color="emerald" />
                <StatCard icon={<Info className="text-amber-400" />} label="Spider Web" value={globalStats.spid} color="amber" />
                <StatCard icon={<Coins className="text-pink-400" />} label="Sum LGNS" value={globalStats.dlgns} color="pink" />
                <StatCard icon={<Layers className="text-cyan-400" />} label="Sum slgns" value={globalStats.dslgns} color="cyan" />
            </div>

            {/* Filter Bar */}
            <div className="bg-slate-800/50 border border-slate-700 p-6 rounded-3xl flex flex-col md:flex-row justify-between items-center gap-6 mb-8 shadow-2xl">
                <div className="relative w-full md:w-[600px]">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-500" />
                    <input 
