                                                                value={editingRemark.value}
                                                                onChange={(e) => setEditingRemark({ ...editingRemark, value: e.target.value })}
                                                                onBlur={() => handleUpdateRemark(addr.aAddress, editingRemark.value)}
                                                                onKeyDown={(e) => {
