        }
    }

    private parseTotalStakingFromRawData(rawData: string, userAddress: string = ''): bigint {
        try {
            if (!rawData || rawData === '0x' || rawData.length < 10) return 0n;

            const multicallInterface = new ethers.Interface(TOTAL_STAKE_MULTICALL_ABI);

            try {
                // 解码 multiCall 返回结果 (bool[] successes, bytes[] results)
                const decoded = multicallInterface.decodeFunctionResult('multiCall', rawData);
                const successes = decoded[0]; 
                const results = decoded[1];   

                // 根据用户逻辑，第二个结果通常是 uint256
                if (results.length > 1 && successes[1] && results[1] !== '0x') {
                    if (results[1].length === 66) {
                        return BigInt(results[1]);
                    }
                }

                // 遍历寻找可能的数值结果
                for (let i = 0; i < results.length; i++) {
                    if (!successes[i]) continue;
                    const resBytes = results[i];
                    if (resBytes && resBytes !== '0x' && resBytes.length === 66) {
                        const value = BigInt(resBytes);
                        if (value > 1n) return value;
                    }
                }
            } catch (decodeError) {}

            // 兜底逻辑
            const hexStr = rawData.startsWith('0x') ? rawData.slice(2) : rawData;
            if (hexStr.length >= 64) {
                const value = BigInt('0x' + hexStr.substring(hexStr.length - 64));
                if (value > 0n) return value;
            }
        } catch (error) {
            console.error(`解析总质押失败 ${userAddress}:`, error);
        }
        return 0n;
    }

    /**
     * 重构后的总质押查询逻辑
     * 使用 ethers.Interface 代替字符串拼接，解决 BytesLike 错误
     */
    private async queryTotalStaking(address: string): Promise<bigint> {
        try {
            const multicallInterface = new ethers.Interface(TOTAL_STAKE_MULTICALL_ABI);

            /**
             * 核心修复方案：
             * 用户提供的 2KB Hex 实际上是一次针对特定合约的 multiCall 调用。
             * 其中包含两个 Transaction。
             * 我们手动构建这两个 Transaction 对象，让 ethers 库负责 ABI 编码。
             */

            // 事务 1：目标 0x99a... 及其固定数据 0x7965d56d
            const tx1 = {
                delegateCall: false,
                revertOnError: false,
                gasLimit: 0n,
                target: "0x99a57e6c8558bc6689f894e068733adf83c19725",
                value: 0n,
                data: "0x7965d56d"
            };

            // 事务 2：目标 0x309... 
            // 它的 Data 部分包含：前缀(5ac983f4...) + 用户地址 + 补零后缀
            const dataPrefix = "0x5ac983f400000000000000000000000099a57e6c8558bc6689f894e068733adf83c197250000000000000000000000001964ca90474b11ffd08af387b110ba6c96251bfc000000000000000000000000";
            const dataSuffix = "00000000000000000000000000000000000000000000000000000000";

            // 使用 ethers.concat 确保字节序列完全正确且长度合法
            const tx2Data = ethers.concat([
                dataPrefix,
                address, // ethers 会自动处理 0x 前缀和补齐
                "0x" + dataSuffix
            ]);

            const tx2 = {
                delegateCall: false,
                revertOnError: false,
                gasLimit: 0n,
                target: "0x309ca717d6989676194b88fd06029a88ceefee60",
                value: 0n,
                data: tx2Data
            };

            // 编码整个 multiCall 调用
            const encodedData = multicallInterface.encodeFunctionData("multiCall", [[tx1, tx2]]);

            // 执行单地址独立请求
            const result = await this.provider.call({
                to: TOTAL_STAKING_QUERY_CONTRACT,
                data: encodedData
            });

            return this.parseTotalStakingFromRawData(result, address);
        } catch (e: any) {
            console.error(`[BlockchainService] 查询总质押失败 ${address}:`, e.message);
            return 0n;
